'use strict';
(()=>{
 const G=JustinGame,game=window.justinClicker;
 const top=document.querySelector('header'),boardButton=document.createElement('button'),accountButton=document.createElement('button');boardButton.id='leaderboard-open';boardButton.textContent='leaderboards';accountButton.id='account-open';accountButton.textContent='log in / create account';top.insertBefore(boardButton,document.querySelector('.music-mode-link'));top.insertBefore(accountButton,boardButton.nextSibling);
 const modeNote=document.createElement('p');modeNote.className='ranked-note';modeNote.id='ranked-note';modeNote.textContent='GUEST MODE · play freely. accounts are only needed to join the leaderboards.';document.querySelector('.instruction').after(modeNote);
 const auth=document.createElement('dialog');auth.className='online-dialog';auth.id='account-dialog';auth.innerHTML='<div class="online-dialog-head"><div><small>THE JUSTIN MEMBERSHIP PROGRAM</small><h2 id="auth-title">welcome back, probably.</h2></div><button type="button" class="close-online" aria-label="Close account window">×</button></div><p id="online-service" role="status"></p><div id="account-profile" hidden><p>Playing ranked as <strong id="account-name"></strong>.</p><p>Your ranked progress is saved to this account. Your guest save is kept separately.</p><button id="account-logout" type="button">log out & play as guest</button></div><div id="account-forms"><div class="auth-tabs"><button id="auth-login" type="button" aria-pressed="true">log in</button><button id="auth-register" type="button" aria-pressed="false">create account</button></div><form id="account-form"><label>username<input id="account-username" autocomplete="username" required minlength="3" maxlength="20" pattern="[A-Za-z0-9_]{3,20}" placeholder="justin_enjoyer"></label><label>password<input id="account-password" type="password" autocomplete="current-password" required minlength="10" maxlength="128"></label><label id="confirm-password-label" hidden>confirm password<input id="account-password-confirm" type="password" autocomplete="new-password" minlength="10" maxlength="128"></label><p id="signup-note" hidden>Creating an account adds your username to public rankings. Ranked mode starts fresh; your guest save stays on this device. No email needed. Password recovery is not available yet, so keep your password safe.</p><button id="account-submit" type="submit">log in</button><button id="continue-guest" type="button">keep playing as guest</button></form></div><p id="account-error" role="status" aria-live="polite"></p>';document.body.append(auth);
 const board=document.createElement('dialog');board.className='online-dialog leaderboard-dialog';board.id='leaderboard-dialog';board.innerHTML='<div class="online-dialog-head"><div><h2>Leaderboard</h2></div><button type="button" class="close-online" aria-label="Close leaderboards">×</button></div><div class="leaderboard-tabs" role="tablist" aria-label="Leaderboard type"><button role="tab" aria-selected="true" data-board="lifetime">lifetime points</button><button role="tab" aria-selected="false" data-board="pps">points / second</button><button role="tab" aria-selected="false" data-board="goat">THE GOATS</button></div><div class="your-rank" id="your-rank">Playing as a guest. Create an account to get ranked.</div><div class="board-table-wrap"><table class="board-table"><thead><tr><th scope="col">rank</th><th scope="col">player</th><th scope="col" id="board-value-label">lifetime points</th></tr></thead><tbody id="leaderboard-rows"></tbody></table><p id="leaderboard-empty" role="status"></p></div><details id="goat-explanation" hidden><summary>how does someone become a GOAT?</summary><p>Lifetime points, points per second, total clicks, face unlocks and your best verified combo all count. Spending points never lowers your lifetime total. Large numbers use a logarithm so a huge lifetime balance doesn’t drown out everything else.</p><code>GOAT score = floor(100 × (4×log10(lifetime+1) + 3×log10(PPS+1) + 2×log10(clicks+1) + 2×extra faces + log10(best combo+1)))</code></details><div class="board-footer"><span id="leaderboard-status" role="status"></span><button id="leaderboard-refresh" type="button">refresh</button><button id="leaderboard-join" type="button">get on the board ↗</button></div>';document.body.append(board);
 const $=id=>document.getElementById(id),number=n=>Math.floor(n||0).toLocaleString();
 let user=null,csrf='',available=false,authMode='login',metric='lifetime',pending=[],batch=null,busy=false,healthy=false,offset=0,boardGeneration=0;
 async function request(url,options={}){const response=await fetch(url,{credentials:'same-origin',...options,headers:{...(options.body?{'Content-Type':'application/json','X-CSRF-Token':csrf}:{}),...options.headers},signal:AbortSignal.timeout(10000)});let data;try{data=await response.json()}catch{throw Error('Online accounts aren’t connected on this version yet. Guest mode still works.')}if(!response.ok){const e=Error(data.error||'Could not reach the game server.');e.status=response.status;throw e}return data}
 function accountUI(){accountButton.textContent=user?user.username+' · ranked':'log in / create account';$('ranked-note').textContent=user?'RANKED MODE · '+user.username+' · progress checked and saved by the game server':'GUEST MODE · play freely. accounts are only needed to join the leaderboards.';$('ranked-note').classList.toggle('is-ranked',Boolean(user));$('account-profile').hidden=!user;$('account-forms').hidden=Boolean(user);$('account-name').textContent=user?.username||'';$('leaderboard-join').hidden=Boolean(user);$('online-service').textContent=available?'': 'Online accounts aren’t connected on this version yet. Guest mode still works.';$('account-submit').disabled=!available}
 function setAuthMode(mode){authMode=mode;$('auth-login').setAttribute('aria-pressed',String(mode==='login'));$('auth-register').setAttribute('aria-pressed',String(mode==='register'));$('auth-title').textContent=mode==='login'?'welcome back, probably.':'become a registered Justin enjoyer.';$('account-submit').textContent=mode==='login'?'log in':'create account & join rankings';$('confirm-password-label').hidden=mode!=='register';$('account-password-confirm').required=mode==='register';$('signup-note').hidden=mode!=='register';$('account-password').autocomplete=mode==='register'?'new-password':'current-password';$('account-error').textContent=''}
 accountButton.onclick=()=>{accountUI();auth.showModal()};boardButton.onclick=()=>{board.showModal();loadBoard()};for(const dialog of [auth,board])dialog.querySelector('.close-online').onclick=()=>dialog.close();$('continue-guest').onclick=()=>auth.close();$('auth-login').onclick=()=>setAuthMode('login');$('auth-register').onclick=()=>setAuthMode('register');
 function enter(data){user=data.user;csrf=data.csrf;available=healthy=true;pending=[];batch=null;offset=data.serverNow-Date.now();game.enterRanked(data.state,data.bestCombo);accountUI();auth.close();$('account-password').value='';$('account-password-confirm').value='';if(board.open)loadBoard()}
 $('account-form').onsubmit=async e=>{e.preventDefault();$('account-error').textContent='';if(authMode==='register'&&$('account-password').value!==$('account-password-confirm').value){$('account-error').textContent='The passwords don’t match.';return}$('account-submit').disabled=true;try{enter(await request('/api/'+authMode,{method:'POST',body:JSON.stringify({username:$('account-username').value.trim(),password:$('account-password').value})}))}catch(error){$('account-error').textContent=error.message;$('account-password').value='';$('account-password-confirm').value=''}finally{$('account-submit').disabled=!available}};
 function replay(snapshot){const prediction=G.clean(snapshot);for(const a of pending){if(a.kind==='click')G.click(prediction);else if(a.kind==='skin')G.buySkin(prediction,a.id);else if(a.kind==='business')G.buyBusiness(prediction,a.id);else if(a.kind==='equip'&&prediction.owned.includes(a.id))prediction.equipped=a.id}return prediction}
 async function flush(){if(!user||busy)return;busy=true;if(!batch)batch={requestId:crypto.randomUUID(),actions:pending.splice(0,100),active:!document.hidden};try{const data=await request('/api/play',{method:'POST',body:JSON.stringify(batch),keepalive:true});batch=null;healthy=true;offset=data.serverNow-Date.now();game.reconcile(replay(data.state));game.setRankedBest(data.bestCombo);if(data.rejected)$('game-message').textContent='The server corrected an update. Very rapid clicks are rate limited in ranked mode.'}catch(error){healthy=false;$('game-message').textContent='Ranked sync paused. Reconnecting… Your guest save is safe.';if(error.status===401){user=null;csrf='';pending=[];batch=null;game.leaveRanked();accountUI();$('account-error').textContent='Your session expired. Please log in again.'}}finally{busy=false}}
 window.justinOnline={active:()=>Boolean(user),connected:()=>Boolean(user)&&healthy,canPlay:()=>Boolean(user)&&healthy&&pending.length<100,clicked:()=>{if(user)pending.push({kind:'click',at:Math.round(Date.now()+offset)})},action:(kind,data)=>{if(!user||!healthy){$('game-message').textContent='Please wait for ranked mode to reconnect.';return}pending.push({kind,...data});flush()}};
 $('account-logout').onclick=async()=>{$('account-logout').disabled=true;try{await flush();if(!healthy)throw Error('Could not finish syncing. Please reconnect before logging out.');await request('/api/logout',{method:'POST',body:'{}'});user=null;csrf='';pending=[];batch=null;game.leaveRanked();accountUI();auth.close();if(board.open)loadBoard()}catch(error){$('account-error').textContent=error.message}finally{$('account-logout').disabled=false}};
 document.querySelectorAll('[data-board]').forEach(button=>button.onclick=()=>{metric=button.dataset.board;document.querySelectorAll('[data-board]').forEach(tab=>tab.setAttribute('aria-selected',String(tab===button)));loadBoard()});
 $('leaderboard-refresh').onclick=()=>loadBoard();$('leaderboard-join').onclick=()=>{board.close();setAuthMode('register');accountUI();auth.showModal()};
 async function loadBoard(){const generation=++boardGeneration;$('board-value-label').textContent={lifetime:'lifetime points',pps:'points / second',goat:'GOAT score'}[metric];$('goat-explanation').hidden=metric!=='goat';$('leaderboard-status').textContent='checking the Justin records…';$('leaderboard-refresh').disabled=true;$('leaderboard-rows').replaceChildren();$('leaderboard-empty').textContent='';try{const data=await request('/api/leaderboard?metric='+metric);if(generation!==boardGeneration)return;for(const row of data.rows){const tr=document.createElement('tr');tr.classList.toggle('is-you',row.id===user?.id);const rank=document.createElement('td'),player=document.createElement('td'),value=document.createElement('td'),name=document.createElement('b'),stats=document.createElement('small');rank.textContent='#'+row.rank;name.textContent=row.username+(row.id===user?.id?' (you)':'');stats.textContent=number(row.pps)+' / sec · '+row.faces+' face'+(row.faces===1?'':'s')+' · best combo '+row.bestCombo;value.textContent=number(row[metric]);player.append(name,stats);tr.append(rank,player,value);$('leaderboard-rows').append(tr)}$('leaderboard-empty').textContent=data.rows.length?'':'No ranked players yet. The first legend could be you.';$('your-rank').textContent=data.me?'Your rank: #'+data.me.rank+' of '+data.total+' · '+number(data.me[metric])+' '+({lifetime:'lifetime points',pps:'points / second',goat:'GOAT score'}[metric]):user?'Your account is ready. Start clicking to climb.':'Guest mode · viewing is free. Create an account to get ranked.';$('leaderboard-status').textContent='live rankings · refreshes every 5 seconds · '+data.total+' player'+(data.total===1?'':'s')}catch(error){if(generation===boardGeneration){$('leaderboard-empty').textContent=error.message;$('leaderboard-status').textContent='rankings unavailable · no scores have been invented'}}finally{if(generation===boardGeneration)$('leaderboard-refresh').disabled=false}}
 setInterval(()=>{if(user&&!document.hidden)flush()},2000);setInterval(()=>{if(board.open&&!document.hidden)loadBoard()},5000);document.addEventListener('visibilitychange',()=>{if(user)flush()});window.addEventListener('pagehide',()=>{if(user)flush()});
 request('/api/session').then(data=>{available=true;if(data.user)enter(data);else accountUI()}).catch(()=>{available=false;accountUI()});accountUI();
})();
